SourceCode.Declaration:
/// <summary>
/// One prioritized identity source within an item identity profile. The resolver walks the
/// lines of a profile in sequence order and stops at the first source that yields a value.
/// </summary>
public class AAXWHSItemIdentityProfileLine extends common
{
}

Method.Source:
/// <summary>
/// Inserts the line and bumps the parent profile version so cached resolutions become
/// stale.
/// </summary>
public void insert()
{
    // Default a blank sequence
    if (!this.LineNum)
    {
        this.LineNum = AAXWHSItemIdentityProfileLine::nextLineNum(this.ProfileId);
    }

    super();

    AAXWHSItemIdentityProfile::bumpVersion(this.ProfileId);
}

/// <summary>
/// Initializes a new line with the next free sequence number of its profile.
/// </summary>
public void initValue()
{
    super();

    if (this.ProfileId)
    {
        this.LineNum = AAXWHSItemIdentityProfileLine::nextLineNum(this.ProfileId);
    }
}

/// <summary>
/// Returns the next free sequence number of a profile, in steps of ten.
/// </summary>
/// <param name = "_profileId">The profile.</param>
/// <returns>The highest existing sequence number plus ten, or ten for an empty profile.</returns>
public static LineNum nextLineNum(AAXWHSItemIdentityProfileId _profileId)
{
    AAXWHSItemIdentityProfileLine profileLine;

    select firstonly maxof(LineNum) from profileLine
        where profileLine.ProfileId == _profileId;

    return profileLine.LineNum + 10;
}

/// <summary>
/// Validates the line and warns when another line of the profile already uses the same source.
/// </summary>
/// <returns>True if the record is valid; otherwise, false.</returns>
public boolean validateWrite()
{
    boolean ret = super();

    if (ret)
    {
        AAXWHSItemIdentityProfileLine sameSourceLine;

        select firstonly RecId, LineNum from sameSourceLine
            order by LineNum
            where sameSourceLine.ProfileId == this.ProfileId
               && sameSourceLine.Source    == this.Source
               && sameSourceLine.RecId     != this.RecId;

        // Warn only
        if (sameSourceLine.RecId != 0)
        {
            warning(strFmt("@AAXWarehouseTools:IdentitySetupWarnDuplicateSource", enum2Str(this.Source), num2Str(sameSourceLine.LineNum, 0, 0, 1, 0)));
        }
    }

    return ret;
}

/// <summary>
/// Updates the line and bumps the parent profile version so cached resolutions become
/// stale.
/// </summary>
public void update()
{
    super();

    AAXWHSItemIdentityProfile::bumpVersion(this.ProfileId);
}

/// <summary>
/// Deletes the line and bumps the version of the profile it belonged to, so cached
/// resolutions become stale.
/// </summary>
public void delete()
{
    // Capture before super() removes the record
    AAXWHSItemIdentityProfileId origProfileId = this.orig().ProfileId;

    super();

    AAXWHSItemIdentityProfile::bumpVersion(origProfileId);
}
